import type { NextRequest } from 'next/server'

export function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl

  // Hub Giuli
  if (pathname.startsWith('/hub-giuli')) {
    if (pathname.startsWith('/hub-giuli/login')) return NextResponse.next()
    const secret = process.env.GIULI_HUB_SECRET
    const session = request.cookies.get('hub_giuli_session')?.value
    if (!secret || !session || session !== secret) {
      return NextResponse.redirect(new URL('/hub-giuli/login', request.url))
    }
    return NextResponse.next()
  }

  // Hub Ramiro
  if (pathname.startsWith('/hub/login')) return NextResponse.next()
  const secret = process.env.HUB_SECRET
  const session = request.cookies.get('hub_session')?.value
  if (!secret || !session || session !== secret) {
    return NextResponse.redirect(new URL('/hub/login', request.url))
  }
  return NextResponse.next()
}

