    .map((law) => {
      const grounded = latest.claims.filter((claim) => claim.provision?.law === law)
      return { law, provision: grounded[0]?.provision ?? null, count: grounded.length }
    })
    .filter((entry) => entry.provision) ?? []

  const stanceOrder = { enables: 0, rejects: 1, unclear: 2 } as const
  const countries = latest
    ? [...latest.countries].sort((a, b) => stanceOrder[a.stance] - stanceOrder[b.stance])
    : []
  const enables = countries.filter((c) => c.stance === "enables").length
  const rejects = countries.filter((c) => c.stance === "rejects").length

  useEffect(() => {
    if (!busy) return
    const ticker = window.setInterval(() => setElapsed(Date.now() - startedAt.current), 100)
    return () => window.clearInterval(ticker)
  }, [busy])

  async function submit(question: string) {
    const asked = question.trim()
    if (!asked || busy) return

    const id = ++requestId.current
    setBusy(true)
    setActiveQuestion(asked)
    setLatest(null)
    setVideoUrl(null)
    setVideoBusy(true)
    setInput("")
    startedAt.current = Date.now()
    setElapsed(0)

    const turn = thread.length
    setThread((t) => [...t, { q: asked }])

    // The scene is generated alongside the answer, never in front of it. The legal
    // reading lands as soon as it is ready; the animation drops into the stage that was
    // already holding its place.
    fetch("/api/video", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question: asked }),
    })
      .then((res) => res.json())
      .then((data) => {
        if (id !== requestId.current) return
        if (data.url) setVideoUrl(data.url)
      })
      .catch(() => {})
      .finally(() => {
        if (id === requestId.current) setVideoBusy(false)
      })

    try {
      // Cala answers each question in isolation, so a follow-up carries the thread and is
      // rewritten server-side into something that stands alone.
      const history = thread.flatMap((t) => (t.a ? [`Q: ${t.q}`, `A: ${t.a.verdict}`] : []))
      // The case file so far: a memo has to reason over everything already established.
      const answered = thread.flatMap((t) => (t.a ? [t.a] : []))
      const gathered = {
        countries: answered.flatMap((a) => a.countries),
        laws: [...new Set(answered.flatMap((a) => a.laws))],
      }

      const res = await fetch("/api/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question: asked, history, gathered }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error ?? "request failed")
      if (id !== requestId.current) return
      setThread((t) => t.map((x, i) => (i === turn ? { ...x, a: data } : x)))
      setLatest(data)
    } catch (error: any) {
      if (id !== requestId.current) return
      setThread((t) => t.map((x, i) => (i === turn ? { ...x, error: error.message } : x)))
    } finally {
      if (id === requestId.current) setBusy(false)
    }
  }

  const showingQuestion = activeQuestion || latest?.question
  const failed = thread[thread.length - 1]?.error

  return (
    <div className="page">
      <header className="masthead">
        <div className="wordmark">
          <MoonMark />
          <span>Mooneto</span>
        </div>
        <p className="tagline">
          Space law, sourced. What is <em>settled</em>, what is <em>disputed</em>,
          and where it is written.
        </p>
      </header>

      <form
        className="ask"
        onSubmit={(event) => {
          event.preventDefault()
          submit(input)
        }}
      >
        <input
          value={input}
          onChange={(event) => setInput(event.target.value)}
          placeholder="Ask about doing business in space"
          aria-label="Space law question"
        />
        <button type="submit" disabled={busy}>
          {busy ? "Consulting" : "Ask"}
        </button>
      </form>

      {!showingQuestion && (
        <section className="opening">
          <p>Start with one of these.</p>
          <div className="openers">
            {SUGGESTIONS.map((suggestion) => (
              <button key={suggestion} type="button" onClick={() => submit(suggestion)}>
                {suggestion}
              </button>
            ))}
          </div>
        </section>
      )}

      {showingQuestion && (
        <main className="answer">
          <section className={`stage${videoUrl ? " has-scene" : ""}`}>
            {videoUrl ? (
              <video
                key={videoUrl}
                className="scene"
                src={videoUrl}
                autoPlay
                muted
                loop
                playsInline
                aria-label="Illustrative animation of the activity in question"
              />
            ) : (
              <div className="scene-pending" role="status">
                <span className="pulse" aria-hidden="true" />
                <span>{videoBusy ? "Drawing the scene" : "No scene for this question"}</span>
              </div>
            )}

            <div className="stage-copy">
              <p className="asked">{showingQuestion}</p>

              {busy && (
                <p className="working" role="status">
                  Reading the treaties
                  <time>{(elapsed / 1000).toFixed(1)}s</time>
                </p>
              )}

              {failed && !busy && <p className="failed">{failed}</p>}

              {latest && !busy && (
                <>
                  <p className={`tone ${latest.tone}`}>{TONE_LABEL[latest.tone]}</p>
                  <p className="verdict">{latest.verdict}</p>
                  {latest.resolved && latest.resolved !== latest.question && (
                    <p className="reading">Read as “{latest.resolved}”</p>
                  )}
                </>
              )}
            </div>
          </section>

          {latest && !busy && (
            <div className="columns">
              <section className="law">
                <h2>The law behind this</h2>
                {evidence.length === 0 ? (
                  <p className="none">
                    No articulated provision in the corpus supports this reading, so nothing
                    here is presented as settled.
                  </p>
                ) : (
                  evidence.map(({ law, provision, count }) => (
                    <article key={law} className="instrument">
                      <h3>
                        {law}
                        {provision?.year ? <span className="year">{provision.year}</span> : null}
                      </h3>
                      <blockquote>{provision?.text}</blockquote>
                      <p className="grounds">
                        {count} {count === 1 ? "claim rests" : "claims rest"} on this provision
                      </p>
                    </article>
                  ))
                )}

                {latest.plan && (
                  <div className="memo">
                    <h2>Recommended route</h2>
                    <ol>
                      {latest.plan.route.map((step, i) => (
                        <li key={i}>
                          {step.step}
                          <span className="basis">{step.basis}</span>
                        </li>
                      ))}
                    </ol>

                    <h2>Open risks</h2>
                    <ul className="risks">
                      {latest.plan.risks.map((risk, i) => (
                        <li key={i}>
                          {risk.risk}
                          <span className="basis">Changes if: {risk.trigger}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </section>

              <aside className="positions">
                <h2>Who reads it how</h2>
                {countries.length === 0 ? (
                  <p className="none">No state position established by the sources.</p>
                ) : (
                  <>
                    <p className="split">
                      <span className="enables">{enables} allow</span>
                      <span className="rejects">{rejects} reject</span>
                    </p>
                    <ul className="states">
                      {countries.map((country) => (
                        <li key={country.name} className={country.stance}>
                          <span className="flag" aria-hidden="true">{flag(country.name)}</span>
                          <span className="name">{country.name}</span>
                          <span className="why">{country.why}</span>
                        </li>
                      ))}
                    </ul>
                  </>
                )}

                {latest.plan && (
                  <div className="confidence">
                    <h2>Legal confidence</h2>
                    <dl>
                      <dt>Ratification</dt>
                      <dd>{latest.plan.confidence.ratification}</dd>
                      <dt>National law</dt>
                      <dd>{latest.plan.confidence.nationalLaw}</dd>
                      <dt>Dissent</dt>
                      <dd>{latest.plan.confidence.dissent}</dd>
                    </dl>
                  </div>
                )}
              </aside>
            </div>
          )}

          {latest && !busy && (
            <section className="followups">
              {SUGGESTIONS.filter((s) => s !== latest.question).map((suggestion) => (
                <button key={suggestion} type="button" onClick={() => submit(suggestion)}>
                  {suggestion}
                </button>
              ))}
            </section>
          )}
        </main>
      )}
    </div>
  )
}

import type { Metadata } from "next"
import { Inter, Newsreader } from "next/font/google"
import "./globals.css"

const inter = Inter({
  subsets: ["latin"],
  variable: "--font-ui",
  display: "swap",
})

// The articulated law is quoted verbatim, so it gets a reading face rather than the
// interface face. The distinction is the point: this is the instrument speaking.
const newsreader = Newsreader({
  subsets: ["latin"],
  variable: "--font-law",
  style: ["normal", "italic"],
  display: "swap",
})

export const metadata: Metadata = {
  title: "Mooneto — space law, sourced",
  description:
    "A visual legal advisor for doing business in space. It tells you what is settled, what is disputed, and where it is written.",
}

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${inter.variable} ${newsreader.variable}`}>
      <body>{children}</body>
    </html>
  )
}

/*
 * Mooneto.
 *
 * The world: a legal instrument read at night. Deep neutral ground, one warm accent that
 * belongs to the Moon and to nothing else, and the quoted law set in a reading face so
 * the instrument is visibly speaking rather than being paraphrased.
 */

:root {
  --ground: #08090e;
  --raised: #101219;
  --sunken: #0b0d13;
  --rule: #1e2130;
  --rule-strong: #2b3043;

  --ink: #eceef5;
  --ink-soft: #a7adc0;
  --ink-faint: #6f7689;

  --moon: #e6c88a;
  --allow: #56c79a;
  --reject: #e8697f;
  --open: #e0a53f;

  --step-1: 0.75rem;
  --step-2: 0.875rem;
  --step-3: 1rem;
  --step-4: 1.375rem;
  --step-5: 2rem;
  --step-6: clamp(2.25rem, 4.2vw, 3.5rem);

  --gap: 1rem;
  --gap-lg: 2rem;
  --gap-xl: 3.5rem;
  --radius: 14px;

  --ease: cubic-bezier(0.16, 1, 0.3, 1);
}

*,
*::before,
*::after { box-sizing: border-box; }

* { margin: 0; }

html {
  background: var(--ground);
  color-scheme: dark;
  scrollbar-color: var(--rule-strong) transparent;
}

body {
  background:
    radial-gradient(1100px 620px at 78% -12%, rgba(230, 200, 138, 0.07), transparent 62%),
    var(--ground);
  color: var(--ink);
  font-family: var(--font-ui), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--step-3);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  min-height: 100dvh;
}

::selection { background: rgba(230, 200, 138, 0.24); color: #fff; }

:focus-visible {
  outline: 2px solid var(--moon);
  outline-offset: 3px;
  border-radius: 4px;
}

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: var(--rule-strong);
  border-radius: 99px;
  border: 3px solid var(--ground);
}
::-webkit-scrollbar-thumb:hover { background: #39405a; }

h1, h2, h3 { font-weight: 600; line-height: 1.18; text-wrap: balance; }

.page {
  max-width: 1180px;
  margin-inline: auto;
  padding: clamp(1.5rem, 4vw, 3rem) clamp(1.25rem, 4vw, 2.5rem) var(--gap-xl);
  display: flex;
  flex-direction: column;
  gap: var(--gap-lg);
}

/* ---------- masthead ---------- */

.masthead { display: flex; flex-direction: column; gap: 0.5rem; }

.wordmark {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: var(--step-4);
  font-weight: 600;
  letter-spacing: -0.03em;
}

.mark { width: 1.35em; height: 1.35em; flex: none; }
.mark-body { fill: var(--moon); }
.mark-crater { fill: rgba(8, 9, 14, 0.42); }

.tagline {
  color: var(--ink-soft);
  font-size: var(--step-2);
  max-width: 62ch;
}
.tagline em { color: var(--ink); font-style: normal; font-weight: 500; }

/* ---------- ask ---------- */

.ask { display: flex; gap: 0.6rem; }

.ask input {
  flex: 1;
  min-width: 0;
  background: var(--sunken);
  border: 1px solid var(--rule);
  border-radius: var(--radius);
  color: var(--ink);
  caret-color: var(--moon);
  font: inherit;
  padding: 0.85rem 1rem;
  transition: border-color 0.18s var(--ease), background 0.18s var(--ease);
}
.ask input::placeholder { color: var(--ink-faint); }
.ask input:hover { border-color: var(--rule-strong); }
.ask input:focus { outline: none; border-color: var(--moon); background: #0d0f16; }

.ask button {
  background: var(--moon);
  color: #17130a;
  border: 0;
  border-radius: var(--radius);
  font: inherit;
  font-weight: 600;
  padding-inline: 1.5rem;
  cursor: pointer;
  transition: filter 0.18s var(--ease);
}
.ask button:hover:not(:disabled) { filter: brightness(1.08); }
.ask button:disabled { opacity: 0.45; cursor: progress; }

/* ---------- opening ---------- */

.opening { display: flex; flex-direction: column; gap: 0.75rem; }
.opening > p { color: var(--ink-faint); font-size: var(--step-2); }
.openers { display: flex; flex-wrap: wrap; gap: 0.6rem; }

.openers button,
.followups button {
  background: transparent;
  border: 1px solid var(--rule);
  border-radius: 99px;
  color: var(--ink-soft);
  font: inherit;
  font-size: var(--step-2);
  padding: 0.5rem 1rem;
  cursor: pointer;
  transition: border-color 0.18s var(--ease), color 0.18s var(--ease);
}
.openers button:hover,
.followups button:hover { border-color: var(--moon); color: var(--ink); }

/* ---------- stage ---------- */

.answer { display: flex; flex-direction: column; gap: var(--gap-xl); }

.stage {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: var(--gap-lg);
  align-items: center;
}

.scene,
.scene-pending {
  aspect-ratio: 16 / 9;
  width: 100%;
  border-radius: var(--radius);
  background: var(--sunken);
  border: 1px solid var(--rule);
}

.scene {
  display: block;
  object-fit: cover;
  animation: arrive 0.7s var(--ease) both;
  box-shadow: 0 26px 60px -28px rgba(0, 0, 0, 0.9);
}

@keyframes arrive {
  from { opacity: 0; transform: scale(0.985); filter: blur(10px); }
  to { opacity: 1; transform: none; filter: blur(0); }
}

.scene-pending {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  color: var(--ink-faint);
  font-size: var(--step-2);
}

.pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--moon);
  animation: breathe 1.6s ease-in-out infinite;
}
@keyframes breathe {
  0%, 100% { opacity: 0.25; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1); }
}

.stage-copy { display: flex; flex-direction: column; gap: 0.75rem; }

.asked {
  color: var(--ink-soft);
  font-size: var(--step-3);
  max-width: 38ch;
}

.working {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  color: var(--ink-faint);
  font-size: var(--step-2);
}
.working time { font-variant-numeric: tabular-nums; color: var(--ink-soft); }

.failed { color: var(--reject); font-size: var(--step-2); }

.tone {
  font-size: var(--step-1);
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
.tone.no { color: var(--reject); }
.tone.yes { color: var(--allow); }
.tone.split { color: var(--open); }

.verdict {
  font-size: var(--step-6);
  font-weight: 600;
  letter-spacing: -0.035em;
  line-height: 1.08;
  max-width: 20ch;
}

.reading { color: var(--ink-faint); font-size: var(--step-2); font-style: italic; }

/* ---------- columns ---------- */

.columns {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
  gap: var(--gap-xl);
  align-items: start;
}

.columns h2 {
  font-size: var(--step-1);
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--ink-faint);
  margin-bottom: var(--gap);
}

.none { color: var(--ink-faint); font-size: var(--step-2); max-width: 60ch; }

/* ---------- the law ---------- */

.instrument { padding-block: 1.35rem; border-top: 1px solid var(--rule); }
.instrument:first-of-type { border-top: 0; padding-top: 0; }

.instrument h3 {
  display: flex;
  align-items: baseline;
  gap: 0.6rem;
  font-size: var(--step-3);
}
.instrument .year {
  color: var(--ink-faint);
  font-size: var(--step-2);
  font-variant-numeric: tabular-nums;
  font-weight: 400;
}

.instrument blockquote {
  font-family: var(--font-law), Georgia, serif;
  font-size: 1.0625rem;
  line-height: 1.6;
  color: var(--ink);
  margin: 0.65rem 0 0.5rem;
  padding-left: 1rem;
  border-left: 1px solid var(--moon);
  max-width: 68ch;
}

.grounds { color: var(--ink-faint); font-size: var(--step-1); }

/* ---------- memo ---------- */

.memo { margin-top: var(--gap-xl); }
.memo h2 { margin-top: var(--gap-lg); }
.memo h2:first-child { margin-top: 0; }

.memo ol,
.memo ul { padding-left: 1.15rem; display: flex; flex-direction: column; gap: 0.85rem; }
.memo li { font-size: var(--step-2); max-width: 66ch; }
.memo ol li::marker { color: var(--moon); font-weight: 600; }
.memo .risks li::marker { color: var(--open); }

.basis {
  display: block;
  color: var(--ink-faint);
  font-size: var(--step-1);
  margin-top: 0.2rem;
}

/* ---------- positions ---------- */

.split {
  display: flex;
  gap: 1rem;
  font-size: var(--step-2);
  font-variant-numeric: tabular-nums;
  margin-bottom: 0.85rem;
}
.split .enables { color: var(--allow); }
.split .rejects { color: var(--reject); }

.states { list-style: none; padding: 0; display: flex; flex-direction: column; }

.states li {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.15rem 0.65rem;
  padding: 0.7rem 0;
  border-top: 1px solid var(--rule);
}
.states li:first-child { border-top: 0; }

.states .flag { font-size: 1.15rem; line-height: 1; grid-row: span 2; }
.states .name { font-size: var(--step-2); font-weight: 500; }
.states .why { color: var(--ink-faint); font-size: var(--step-1); }

.states li.enables .name { color: var(--allow); }
.states li.rejects .name { color: var(--reject); }
.states li.unclear .name { color: var(--ink-soft); }

.confidence { margin-top: var(--gap-xl); }
.confidence dl { display: flex; flex-direction: column; gap: 0.7rem; }
.confidence dt {
  color: var(--ink-faint);
  font-size: var(--step-1);
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.confidence dd { font-size: var(--step-2); max-width: 46ch; }

/* ---------- followups ---------- */

.followups { display: flex; flex-wrap: wrap; gap: 0.6rem; }

/* ---------- narrow ---------- */

@media (max-width: 900px) {
  .stage,
  .columns { grid-template-columns: minmax(0, 1fr); }
  .stage { gap: var(--gap); }
  .verdict { max-width: none; }
  .asked { max-width: none; }
}

@media (prefers-reduced-motion: reduce) {
  .scene { animation: none; }
  .pulse { animation: none; opacity: 0.7; }
}

